export default function index({ body }) {
  if (!Array.isArray(body?.hrefs)) throw Error("Invalid essay index");
  const urls = [];
  for (const h of body.hrefs.slice(0, 3)) {
    if (typeof h !== "string" || !h) throw Error("Invalid essay link");
    let path = h;
    if (/^https?:\/\/www\.paulgraham\.com\//i.test(path))
      path = path.replace(/^https?:\/\/www\.paulgraham\.com\//i, "");
    else if (path.startsWith("/")) path = path.slice(1);
    if (!/^[a-z0-9_./-]+$/i.test(path) || path.includes("..") || path.startsWith("/"))
      throw Error("Unexpected essay link");
    urls.push("https://www.paulgraham.com/" + path);
  }
  return { urls };
}

