export default function next({ urls, previous, collected }) {
  const index = previous?.index ?? 0,
    url = urls[index],
    pages = collected?.pages ?? previous?.pages ?? [];
  return {
    state: { index: index + (url ? 1 : 0), pages },
    more: !!url,
    url: url ?? "https://www.paulgraham.com/",
  };
}

