export default function parts({ pages }) {
  const parts = [];
  for (const p of pages) {
    for (let i = 0; i < p.html.length; i += 4000)
      parts.push({ url: p.url, text: p.html.slice(i, i + 4000) });
  }
  return { parts };
}

