export default function next({ pages, summaries, previous, collected }) {
  const index = previous?.index ?? 0,
    p = pages[index],
    results = collected?.results ?? previous?.results ?? [],
    text = p
      ? summaries
          .filter((x) => x.url === p.url)
          .map((x) => x.summary)
          .join("\n\n")
      : "";
  if (p && !text) throw Error("Missing chunk summaries");
  return {
    state: { index: index + (p ? 1 : 0), results },
    more: !!p,
    url: p?.url ?? "",
    title: p?.title ?? "",
    text,
  };
}

